public static int Main()
{
    var stopwatch = Stopwatch.StartNew();
    long checksum = 0;
    while (stopwatch.Elapsed < TimeSpan.FromSeconds(6))
    {
        foreach (var category in Categories)
        {
            var inputExtensions = FormatCatalog.GetInputExtensions(category);
            checksum += inputExtensions.Count;

            var contentExtensions = ContentFormatCatalog.GetInputExtensions(category);
            checksum += contentExtensions.Count;

            foreach (var extension in Extensions)
            {
                checksum += (int)FormatCatalog.DetectCategoryByExtension(extension);
                checksum += (int)ContentFormatCatalog.DetectCategoryByExtension(extension);
                checksum += FormatCatalog.FindByExtension(extension) is null ? 0 : 1;
                checksum += ContentFormatCatalog.FindByExtension(extension) is null ? 0 : 1;
            }
        }
    }

    Console.WriteLine($"checksum={checksum} elapsed={stopwatch.Elapsed.TotalSeconds:0.00}s");
    return 0;
}
